using System.Text.RegularExpressions;
using DbPilot.Models;
using DbPilot.Providers;

namespace DbPilot.Services;
public static partial class SchemaTools
{
    public static string ValidType(string type){if(!TypePattern().IsMatch(type.Trim()))throw new ArgumentException("字段类型格式无效。");return type.Trim();}
    [GeneratedRegex(@"^[\p{L}_][\p{L}\p{N}_ .]*(\(\s*(\d+|max)(\s*,\s*\d+)?\s*\))?(\s+unsigned|\s+with(out)? time zone)?(\[\])?$",RegexOptions.IgnoreCase)]private static partial Regex TypePattern();
    public static string ColumnSql(IDbProvider provider,DatabaseKind kind,ColumnInfo c)
    {
        var type=ValidType(c.Type);var name=provider.Quote(c.Name);
        if(kind==DatabaseKind.TDengine){if(c.HasDefault||c.IsIdentity)throw new NotSupportedException("TDengine 字段不支持此默认表达式或自增设置。");return name+" "+type;}
        if(kind==DatabaseKind.SqlServer&&type.ToLowerInvariant() is "rowversion" or "timestamp")return name+" "+type;
        if(c.GenerationExpression.Length>0)return kind switch{
            DatabaseKind.SqlServer=>name+" AS ("+c.GenerationExpression+")"+(c.Stored?" PERSISTED":""),
            DatabaseKind.PostgreSQL=>name+" "+type+" GENERATED ALWAYS AS ("+c.GenerationExpression+") STORED",
            DatabaseKind.MySQL=>name+" "+type+" GENERATED ALWAYS AS ("+c.GenerationExpression+")"+(c.Stored?" STORED":" VIRTUAL"),
            _=>throw new NotSupportedException("该数据库不支持计算列。")};
        if(c.IsGenerated&&!c.IsIdentity)throw new NotSupportedException($"字段 {c.Name} 缺少可还原的生成定义，禁止生成不完整建表脚本。");
        var generated=c.IsIdentity;
        var auto=generated ? kind switch{DatabaseKind.MySQL=>" AUTO_INCREMENT",DatabaseKind.PostgreSQL=>" GENERATED BY DEFAULT AS IDENTITY",DatabaseKind.SqlServer=>" IDENTITY(1,1)",_=>""}:"";
        return name+" "+type+auto+(c.Nullable?" NULL":" NOT NULL")+(!generated&&c.HasDefault&&!string.IsNullOrEmpty(c.Default)?" DEFAULT "+c.Default:"");
    }
    public static string CreateTable(IDbProvider provider,DatabaseKind kind,DbObject table,IReadOnlyList<ColumnInfo> columns)
    {
        if(columns.Count==0)throw new ArgumentException("至少需要一个字段。");
        var fields=columns.Where(c=>!c.IsTag).Select(c=>ColumnSql(provider,kind,c)).ToList();
        var keys=columns.Where(c=>c.PrimaryKey).Select(c=>provider.Quote(c.Name)).ToArray();
        if(keys.Length>0 && kind!=DatabaseKind.TDengine)fields.Add("PRIMARY KEY ("+string.Join(", ",keys)+")");
        return $"CREATE {(table.Kind=="超级表"?"STABLE":"TABLE")} {provider.Qualified(table)} (\n  {string.Join(",\n  ",fields)}\n)"+
            (columns.Any(c=>c.IsTag)?" TAGS ("+string.Join(", ",columns.Where(c=>c.IsTag).Select(c=>provider.Quote(c.Name)+" "+ValidType(c.Type)))+")":"")+";";
    }
    public static string ForeignKeySql(IDbProvider provider,DbObject table,IReadOnlyList<ForeignKeyInfo> keys)
    {
        string Action(string value)=>value.ToUpperInvariant() is "NO ACTION" or "RESTRICT" or "CASCADE" or "SET NULL" or "SET DEFAULT"?value.ToUpperInvariant():throw new ArgumentException("未知的外键引用动作。");
        return $"ALTER TABLE {provider.Qualified(table)} ADD CONSTRAINT {provider.Quote(keys[0].Name)} FOREIGN KEY ({string.Join(", ",keys.Select(k=>provider.Quote(k.Column)))}) REFERENCES {provider.Qualified(new(table.Database,keys[0].ReferencedSchema,keys[0].ReferencedTable,"表"))} ({string.Join(", ",keys.Select(k=>provider.Quote(k.ReferencedColumn)))}) ON DELETE {Action(keys[0].OnDelete)} ON UPDATE {Action(keys[0].OnUpdate)}"+(keys[0].Deferrable?" DEFERRABLE "+(keys[0].InitiallyDeferred?"INITIALLY DEFERRED":"INITIALLY IMMEDIATE"):"")+";";
    }
    public static string MapType(string type,DatabaseKind source,DatabaseKind target)
    {
        if(source==target)return type;var t=type.ToLowerInvariant();
        if(t.Contains("int"))return t.Contains("big")?"BIGINT":"INT";
        if(t.Contains("bool")||t=="bit")return target==DatabaseKind.PostgreSQL?"BOOLEAN":target==DatabaseKind.SqlServer?"BIT":"BOOL";
        if(t.Contains("timestamp")||t.Contains("date")||t.Contains("time"))return target switch{DatabaseKind.SqlServer=>"DATETIME2",DatabaseKind.MySQL=>"DATETIME(6)",_=>"TIMESTAMP"};
        if(t.Contains("double")||t.Contains("float")||t=="real")return target==DatabaseKind.PostgreSQL?"DOUBLE PRECISION":target==DatabaseKind.SqlServer?"FLOAT":"DOUBLE";
        if(t.Contains("numeric")||t.Contains("decimal"))return t.Replace("numeric","decimal");
        if(t.Contains("binary")||t.Contains("blob")||t=="bytea")return target switch{DatabaseKind.PostgreSQL=>"BYTEA",DatabaseKind.SqlServer=>"VARBINARY(MAX)",_=>"LONGBLOB"};
        if(t is "uuid" or "uniqueidentifier")return target==DatabaseKind.PostgreSQL?"UUID":target==DatabaseKind.SqlServer?"UNIQUEIDENTIFIER":"VARCHAR(36)";
        return target==DatabaseKind.SqlServer?"NVARCHAR(MAX)":target==DatabaseKind.MySQL?"LONGTEXT":"TEXT";
    }
    public static IReadOnlyList<SchemaDifference> Compare(IDbProvider target,DatabaseKind kind,DbObject table,IReadOnlyList<ColumnInfo> source,IReadOnlyList<ColumnInfo> destination,string? targetPrimaryKey=null)
    {
        var differences=new List<SchemaDifference>();var existing=destination.ToDictionary(c=>c.Name,StringComparer.Ordinal);
        foreach(var column in source){
            if(!existing.TryGetValue(column.Name,out var old)){differences.Add(new("新增字段",column.Name,column.Type,$"ALTER TABLE {target.Qualified(table)} ADD {ColumnSql(target,kind,column)};",false));continue;}
            if(column.Type!=old.Type || column.Nullable!=old.Nullable || column.Default!=old.Default){
                var sql=kind switch{
                    DatabaseKind.PostgreSQL=>$"ALTER TABLE {target.Qualified(table)} ALTER COLUMN {target.Quote(column.Name)} TYPE {ValidType(column.Type)};\nALTER TABLE {target.Qualified(table)} ALTER COLUMN {target.Quote(column.Name)} {(column.Nullable?"DROP":"SET")} NOT NULL;\nALTER TABLE {target.Qualified(table)} ALTER COLUMN {target.Quote(column.Name)} {(column.HasDefault?"SET DEFAULT "+column.Default:"DROP DEFAULT")};",
                    DatabaseKind.MySQL=>$"ALTER TABLE {target.Qualified(table)} MODIFY COLUMN {ColumnSql(target,kind,column)};",
                    DatabaseKind.SqlServer=>$"ALTER TABLE {target.Qualified(table)} ALTER COLUMN {target.Quote(column.Name)} {ValidType(column.Type)} {(column.Nullable?"NULL":"NOT NULL")};\nGO\n"+SqlServerDefault(target,table,column),
                    _=>$"ALTER TABLE {target.Qualified(table)} MODIFY COLUMN {target.Quote(column.Name)} {ValidType(column.Type)};"};
                differences.Add(new("修改字段",column.Name,$"{old.Type} → {column.Type}; NULL {old.Nullable} → {column.Nullable}",sql,true));
            }
        }
        foreach(var c in destination.Where(c=>source.All(s=>s.Name!=c.Name)))differences.Add(new("删除字段",c.Name,c.Type,$"ALTER TABLE {target.Qualified(table)} DROP COLUMN {target.Quote(c.Name)};",true));
        var oldKeys=destination.Where(c=>c.PrimaryKey).Select(c=>c.Name).ToArray();var newKeys=source.Where(c=>c.PrimaryKey).Select(c=>c.Name).ToArray();
        if(!oldKeys.SequenceEqual(newKeys)&&kind!=DatabaseKind.TDengine){
            var sql="";
            if(oldKeys.Length>0){
                if(kind==DatabaseKind.MySQL)sql=$"ALTER TABLE {target.Qualified(table)} DROP PRIMARY KEY;\n";
                else if(!string.IsNullOrEmpty(targetPrimaryKey))sql=$"ALTER TABLE {target.Qualified(table)} DROP CONSTRAINT {target.Quote(targetPrimaryKey)};\n";
                else throw new InvalidOperationException("无法读取目标主键约束名称，不能生成主键修改计划。");
            }
            // Drop before field changes so removed key columns do not leave invalid constraints.
            if(sql.Length>0)differences.Insert(0,new("删除旧主键",table.Name,string.Join(", ",oldKeys),sql,true));
            if(newKeys.Length>0)differences.Add(new("建立主键",table.Name,string.Join(", ",newKeys),$"ALTER TABLE {target.Qualified(table)} ADD PRIMARY KEY ({string.Join(", ",newKeys.Select(target.Quote))});",true));
        }
        if(kind==DatabaseKind.SqlServer)for(int i=0;i<differences.Count;i++)differences[i]=differences[i] with{Sql=differences[i].Sql+"\nGO"};
        return differences;
    }
    public static string SqlServerDefault(IDbProvider provider,DbObject table,ColumnInfo column)
    {
        var literal=DataValues.String(provider.Qualified(table),DatabaseKind.SqlServer);var field=DataValues.String(column.Name,DatabaseKind.SqlServer);
        return $"DECLARE @dbpilot_default sysname;\nSELECT @dbpilot_default=dc.name FROM sys.default_constraints dc JOIN sys.columns c ON c.object_id=dc.parent_object_id AND c.column_id=dc.parent_column_id WHERE dc.parent_object_id=OBJECT_ID({literal}) AND c.name={field};\nIF @dbpilot_default IS NOT NULL EXEC({DataValues.String("ALTER TABLE "+provider.Qualified(table)+" DROP CONSTRAINT ",DatabaseKind.SqlServer)}+QUOTENAME(@dbpilot_default));\n"+(column.HasDefault?$"ALTER TABLE {provider.Qualified(table)} ADD DEFAULT {column.Default} FOR {provider.Quote(column.Name)};\n":"")+"GO";
    }
}
